# -*- coding: utf-8 -*-
# Content of Section III (sections 1-5) for the redesigned UI.
# Each module: (heading2, intro, [screens]); screen: (heading3, description, [(img, caption)], [(field, description)])

INTRO_TITLE = "Section III – Functional Requirements (updated to the redesigned Web UI)"
INTRO_TEXT = ("This section replaces Section III of Report-3. Every screen figure is a frame of the ModMove UI redesign in Figma "
              "(file “ModMove – UI Redesign”, design system v1.0, 13/11/2026). The redesign was built from the running web application "
              "explored on 12/11/2026 and keeps the same functions, data and business flow; only the layout and visual design changed. "
              "Screen labels are shown in Vietnamese as they appear in the UI. Business rules are referenced by their GB codes from Part V.1.")

